// CSD_RATIONALE_BEGIN
// Root-cause analysis:
// - Best (40.8%): `next == "<<"` never matched Qwen's space-prefixed " <<" token.
//   ALL generation was unconstrained; the model wrote natural spans sometimes
//   correctly (40.8%) and sometimes used {n} curly braces or ** (5 syntax failures).
// - Attempt 60 (0%): Fixed detection with RenderedEndsWith but used CloseSpanIfComplete,
//   which closes after a single variable token (parser considers "n" complete) → <<n>> spans.
// - Attempt 61 (30.6%): Fully unconstrained with guidance; model still produced {n}.
//
// This attempt: FORCED constrained span content via RenderedEndsWith + CloseSpanWithinBudget.
//
// Key insight: CloseSpanWithinBudget generates forward (dead-end-aware) and tracks the
// LONGEST complete parse prefix seen, closing there. Unlike CloseSpanIfComplete (which
// fires immediately on the first complete token), CloseSpanWithinBudget continues past
// "n" (complete), generates "* frac_1 * frac_2" (also complete), and closes at the
// longest prefix — producing <<n * frac_1 * frac_2>> instead of <<n>>.
// Parser hard-masks also reject { } and ** tokens, eliminating the 5 syntax failures.
//
// Strategy:
// 1. Guidance to fix the {n} → n variable naming confusion.
// 2. Handle any initial open span in prologue via CloseSpanWithinBudget.
// 3. Main loop: generate unconstrained; on RenderedEndsWith(generated, "<<"):
//    a. Enter span with EnterObservedConstrainedSpan (cost 0).
//    b. CloseSpanWithinBudget(min(50, remaining)) — generates expression tokens and
//       closes with ">>" at the longest complete arithmetic prefix within budget.
//    c. Reset insideConstrainedOut := false for subsequent unconstrained generation.
// 4. Repeat until EOS or budget exhaustion.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: insideConstrainedOut := insideConstrained,
//     currentConstrainedOut := currentConstrained. Precondition guarantees validity
//     whenever insideConstrained holds.
//
//   Prologue (initial open span, if any): CloseSpanWithinBudget postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). We then
//     unconditionally reset insideConstrainedOut := false, making the implication
//     vacuously true. ✓
//
//   While loop — no RenderedEndsWith trigger: insideConstrainedOut is never modified
//     (it is false from prologue or initialization). The implication is vacuously true. ✓
//
//   While loop — RenderedEndsWith branch:
//     EnterObservedConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition. ✓
//     CloseSpanWithinBudget postcondition guarantees
//       insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//     Forced reset (insideConstrainedOut := false; currentConstrainedOut := []) makes
//     the implication vacuously true. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Initialization: generated = generatedPrefix, steps = 0. ✓
//
//   Prologue: CloseSpanWithinBudget(initBudget) gives |cg| <= |generated| + initBudget.
//     steps := 0 + initBudget. So |generated| <= |generatedPrefix| + steps. ✓
//
//   While loop — EOS branch: steps += 1, no append. |generated| unchanged ≤ |generatedPrefix| + steps. ✓
//
//   While loop — no RenderedEndsWith: steps += 1, generated += [next] (1 token).
//     |generated_new| = |generated_old| + 1 <= |generatedPrefix| + (steps - 1) + 1 = |generatedPrefix| + steps. ✓
//
//   While loop — RenderedEndsWith branch:
//     After UnconstrainedStep+append: steps = s+1, |generated| <= |generatedPrefix| + (s+1).
//     EnterObservedConstrainedSpan: generated and steps unchanged. ✓
//     remaining = maxSteps - (s+1), spanBudget <= remaining.
//     CloseSpanWithinBudget(spanBudget): |generated_new| <= |generated_old| + spanBudget.
//     steps_new = (s+1) + spanBudget <= (s+1) + (maxSteps - s - 1) = maxSteps. ✓
//     |generated_new| <= |generatedPrefix| + (s+1) + spanBudget = |generatedPrefix| + steps_new. ✓
//     Reset: no change to generated or steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step by step.\n" +
  "Write intermediate symbolic computations and the final answer inside << >> delimiters.\n" +
  "CRITICAL VARIABLE NAMING: In the problem, {name} is a placeholder meaning the variable\n" +
  "is called 'name'. Inside << >> spans, write variable names WITHOUT curly braces.\n" +
  "CORRECT: <<n * frac_1>>          WRONG: <<{n} * {frac_1}>>\n" +
  "CORRECT: <<end_time - start_time>> WRONG: <<{end_time} - {start_time}>>\n" +
  "CORRECT: <<n0 * (r + 1)>>        WRONG: <<{n0} * ({r} + 1)>>\n" +
  "Allowed operators inside << >>: + - * / // ( ) only.\n" +
  "Do NOT use ** for powers (write x * x instead of x**2).\n" +
  "Use // for integer division when quantities must be whole numbers.\n" +
  "The LAST << >> span must be the complete final answer as a single arithmetic expression.");

var steps: nat := 0;

// Prologue: close any initial open constrained span, then reset to unconstrained mode.
if insideConstrainedOut && steps < maxSteps {
  var initBudget: nat := if maxSteps >= 50 then 50 else maxSteps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, initBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + initBudget;
  // Force reset to unconstrained regardless of close outcome.
  insideConstrainedOut := false;
  currentConstrainedOut := [];
}

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Generate one unconstrained token (allows model to produce reasoning text).
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];

  // Detect span opening using RenderedEndsWith (handles " <<", "<<", etc.).
  if RenderedEndsWith(generated, "<<") && steps < maxSteps {
    // Enter the observed constrained span (cost 0, generated unchanged).
    var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;

    // Drive constrained span content with CloseSpanWithinBudget:
    // generates forward tracking the longest complete arithmetic expression,
    // then closes at that longest prefix with ">>".
    // Parser hard-mask prevents {, }, **, and other invalid tokens.
    var remaining: nat := maxSteps - steps;
    var spanBudget: nat := if remaining >= 50 then 50 else remaining;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + spanBudget;

    // Reset to unconstrained for subsequent generation (whether or not span closed).
    insideConstrainedOut := false;
    currentConstrainedOut := [];
  }
}

cost := steps;

